// 현재 Loop에서 처리 중이던 프로그램
const program = $("프로그램 상세 순회").item.json;

// HTTP Request 노드가 반환한 오류 정보
const errorData = $json;

const errorMessage =
  errorData.error?.message ??
  errorData.message ??
  errorData.description ??
  "상세 페이지 요청에 실패했습니다.";

const statusCode =
  errorData.error?.statusCode ??
  errorData.error?.httpCode ??
  errorData.statusCode ??
  null;

return {
  json: {
    requestSucceeded: false,

    sourcePostId:
      program.sourcePostId ?? null,

    title:
      program.title ?? null,

    sourceUrl:
      program.sourceUrl ?? null,

    statusCode,

    errorMessage:
      String(errorMessage),

    failedAt:
      new Date().toISOString(),
  },
};

const program = $json;
const parseWarnings = [];

const isEmpty = (value) => {
  return value === null ||
    value === undefined ||
    String(value).trim() === "";
};

const isValidDate = (value) => {
  return /^\d{4}-\d{2}-\d{2}$/.test(
    String(value ?? "")
  );
};

// 필수값 검사
if (isEmpty(program.sourcePostId)) {
  parseWarnings.push("게시글 식별값이 없습니다.");
}

if (isEmpty(program.title)) {
  parseWarnings.push("프로그램명이 없습니다.");
}

if (isEmpty(program.sourceUrl)) {
  parseWarnings.push("원본 상세 페이지 URL이 없습니다.");
}

if (
  isEmpty(program.rawText) ||
  String(program.rawText).trim().length < 30
) {
  parseWarnings.push(
    "원본 본문이 없거나 지나치게 짧습니다."
  );
}

// 날짜 검사
if (
  program.educationStartDate &&
  !isValidDate(program.educationStartDate)
) {
  parseWarnings.push(
    "교육 시작일 형식을 확인해야 합니다."
  );
}

if (
  program.educationEndDate &&
  !isValidDate(program.educationEndDate)
) {
  parseWarnings.push(
    "교육 종료일 형식을 확인해야 합니다."
  );
}

if (
  isValidDate(program.educationStartDate) &&
  isValidDate(program.educationEndDate) &&
  program.educationStartDate >
    program.educationEndDate
) {
  parseWarnings.push(
    "교육 시작일이 종료일보다 늦습니다."
  );
}

// 숫자 검사
if (
  program.capacity !== null &&
  program.capacity !== undefined &&
  (
    typeof program.capacity !== "number" ||
    Number.isNaN(program.capacity) ||
    program.capacity < 0
  )
) {
  parseWarnings.push(
    "모집인원 값이 올바른 숫자가 아닙니다."
  );
}

if (
  program.currentApplicants !== null &&
  program.currentApplicants !== undefined &&
  (
    typeof program.currentApplicants !== "number" ||
    Number.isNaN(program.currentApplicants) ||
    program.currentApplicants < 0
  )
) {
  parseWarnings.push(
    "현재 신청인원 값이 올바른 숫자가 아닙니다."
  );
}

// 지나치게 긴 구조화 필드 검사
if (
  program.location &&
  String(program.location).length > 250
) {
  parseWarnings.push(
    "교육 장소가 비정상적으로 길게 추출되었습니다."
  );
}

if (
  program.feeText &&
  String(program.feeText).length > 150
) {
  parseWarnings.push(
    "비용 정보가 비정상적으로 길게 추출되었습니다."
  );
}

if (
  program.contactText &&
  !/^0\d{1,2}-\d{3,4}-\d{4}$/.test(
    String(program.contactText).trim()
  )
) {
  parseWarnings.push(
    "문의처가 일반적인 전화번호 형식이 아닙니다."
  );
}

// 회차 중복 검사
const sessions = Array.isArray(program.sessions)
  ? program.sessions
  : [];

const sessionNumbers = sessions
  .map((session) => session?.sessionNumber)
  .filter((value) => value !== null && value !== undefined);

if (
  new Set(sessionNumbers).size !==
  sessionNumbers.length
) {
  parseWarnings.push(
    "동일한 회차 번호가 반복됩니다."
  );
}

// 첨부파일 검사
const attachments = Array.isArray(program.attachments)
  ? program.attachments
  : [];

if (
  attachments.some(
    (attachment) => !attachment?.fileUrl
  )
) {
  parseWarnings.push(
    "URL이 없는 첨부파일이 있습니다."
  );
}

if (
  attachments.length > 0 &&
  sessions.length === 0
) {
  parseWarnings.push(
    "세부 회차 정보가 첨부파일에만 존재할 수 있습니다."
  );
}

return {
  json: {
    ...program,
    requestSucceeded: true,
    parseWarnings,
  },
};

const discoveredItems = $(
  "프로그램별 항목 생성"
).all().map((item) => item.json);

const requestedListPages = new Set(
  discoveredItems
    .map((item) => Number(item.listPage))
    .filter((value) => Number.isFinite(value))
).size;

const results = $input.all().map(
  (item) => item.json
);

/**
 * 노드 이름이 변경됐더라도 후보 이름 중
 * 존재하는 노드의 item 개수를 가져옵니다.
 */
const getNodeItemCount = (nodeNames) => {
  for (const nodeName of nodeNames) {
    try {
      return $(nodeName).all().length;
    } catch {
      // 해당 이름의 노드가 없으면 다음 후보 확인
    }
  }

  return null;
};

const successfulPrograms = results.filter(
  (item) => item.requestSucceeded === true
);

const failedPrograms = results.filter(
  (item) => item.requestSucceeded === false
);

const warningPrograms = successfulPrograms.filter(
  (item) =>
    Array.isArray(item.parseWarnings) &&
    item.parseWarnings.length > 0
);

/**
 * parseWarnings의 경고 문구별 발생 횟수를 집계합니다.
 */
const warningCountsByReason = {};

for (const program of warningPrograms) {
  const warnings = Array.isArray(
    program.parseWarnings
  )
    ? program.parseWarnings
    : [];

  for (const warning of warnings) {
    const warningText = String(
      warning ?? ""
    ).trim();

    if (!warningText) {
      continue;
    }

    warningCountsByReason[warningText] =
      (warningCountsByReason[warningText] ?? 0) + 1;
  }
}

/**
 * 프로그램별 경고 사유도 확인할 수 있도록 정리합니다.
 */
const warningDetails = warningPrograms.map(
  (program) => ({
    sourcePostId:
      program.sourcePostId ?? null,

    sourceUrl:
      program.sourceUrl ?? null,

    warnings: Array.isArray(
      program.parseWarnings
    )
      ? program.parseWarnings
      : [],
  })
);

const programsWithAttachments =
  successfulPrograms.filter(
    (item) =>
      Array.isArray(item.attachments) &&
      item.attachments.length > 0
  );

const attachments = successfulPrograms.flatMap(
  (item) =>
    Array.isArray(item.attachments)
      ? item.attachments
      : []
);

const attachmentCounts = {
  hwp: 0,
  pdf: 0,
  image: 0,
  other: 0,
  unknown: 0,
};

const imageTypes = new Set([
  "jpg",
  "jpeg",
  "png",
  "gif",
  "webp",
  "bmp",
  "tif",
  "tiff",
]);

for (const attachment of attachments) {
  const fileType = String(
    attachment?.fileType ?? ""
  )
    .trim()
    .toLowerCase();

  if (!fileType) {
    attachmentCounts.unknown += 1;
  } else if (
    fileType === "hwp" ||
    fileType === "hwpx"
  ) {
    attachmentCounts.hwp += 1;
  } else if (fileType === "pdf") {
    attachmentCounts.pdf += 1;
  } else if (imageTypes.has(fileType)) {
    attachmentCounts.image += 1;
  } else {
    attachmentCounts.other += 1;
  }
}

/**
 * 첨부파일 확장자별 상세 집계입니다.
 */
const attachmentCountsByExtension = {};

for (const attachment of attachments) {
  const fileType =
    String(attachment?.fileType ?? "")
      .trim()
      .toLowerCase() || "unknown";

  attachmentCountsByExtension[fileType] =
    (attachmentCountsByExtension[fileType] ?? 0) + 1;
}

/**
 * 수집 결과에 포함된 시간 중 가장 빠른 시간과
 * 가장 늦은 시간을 기준으로 처리 시간을 계산합니다.
 */
const timestamps = results
  .map(
    (item) =>
      item.crawledAt ??
      item.failedAt ??
      null
  )
  .filter(Boolean)
  .map((value) =>
    new Date(value).getTime()
  )
  .filter((value) =>
    Number.isFinite(value)
  );

const startedAt =
  timestamps.length > 0
    ? new Date(
        Math.min(...timestamps)
      ).toISOString()
    : null;

const finishedAt =
  timestamps.length > 0
    ? new Date(
        Math.max(...timestamps)
      ).toISOString()
    : null;

const durationSeconds =
  timestamps.length > 1
    ? Math.round(
        (
          Math.max(...timestamps) -
          Math.min(...timestamps)
        ) / 1000
      )
    : 0;

const discoveredPrograms =
  getNodeItemCount([
    "프로그램별 항목 생성",
  ]);

const afterIdDeduplication =
  getNodeItemCount([
    "목록 중복 제거_ID",
  ]);

const afterUrlDeduplication =
  getNodeItemCount([
    "목록 중복 제거_URL",
  ]);

const detailRequestTargetCount =
  getNodeItemCount([
    "상세 수집 건수 제한",
    "Limit",
  ]);

const duplicateCountById =
  Number.isFinite(discoveredPrograms) &&
  Number.isFinite(afterIdDeduplication)
    ? discoveredPrograms -
      afterIdDeduplication
    : null;

const duplicateCountByUrl =
  Number.isFinite(afterIdDeduplication) &&
  Number.isFinite(afterUrlDeduplication)
    ? afterIdDeduplication -
      afterUrlDeduplication
    : null;

return [
  {
    json: {
      requestedListPages,

      discoveredPrograms,

      afterIdDeduplication,

      duplicateCountById,

      afterUrlDeduplication,

      duplicateCountByUrl,

      detailRequestTargetCount,

      detailSuccessCount:
        successfulPrograms.length,

      detailFailureCount:
        failedPrograms.length,

      failedPostIds: failedPrograms
        .map(
          (item) => item.sourcePostId
        )
        .filter(Boolean),

      failedUrls: failedPrograms
        .map(
          (item) => item.sourceUrl
        )
        .filter(Boolean),

      failedDetails: failedPrograms.map(
        (item) => ({
          sourcePostId:
            item.sourcePostId ?? null,

          sourceUrl:
            item.sourceUrl ?? null,

          statusCode:
            item.statusCode ?? null,

          errorMessage:
            item.errorMessage ?? null,

          failedAt:
            item.failedAt ?? null,
        })
      ),

      warningProgramCount:
        warningPrograms.length,

      warningPostIds: warningPrograms
        .map(
          (item) => item.sourcePostId
        )
        .filter(Boolean),

      warningCountsByReason,

      warningDetails,

      programsWithAttachments:
        programsWithAttachments.length,

      totalAttachmentCount:
        attachments.length,

      attachmentCounts,

      attachmentCountsByExtension,

      finalResultCount:
        results.length,

      finalProgramCount:
        successfulPrograms.length,

      startedAt,
      finishedAt,
      durationSeconds,
    },
  },
];

// 상세 정보 추출 노드의 현재 결과
const extracted = $json;

// Loop에서 현재 처리 중인 프로그램의 목록 정보
const program = $("프로그램 상세 순회").item.json;

// 워크플로우 시작 부분의 공통 설정
const config = $("수집 설정").first().json;

/**
 * 일반 문자열의 공백을 정리합니다.
 */
const cleanText = (value) => {
  return String(value ?? "")
    .replace(/\s+/g, " ")
    .trim();
};

/**
 * 상세 본문의 base64 이미지와 불필요한 HTML 문자열을 정리합니다.
 */
const cleanContentText = (value) => {
  return String(value ?? "")
    // [data:image/png;base64,...] 형식 제거
    .replace(
      /\[data:image\/[a-z0-9.+-]+;base64,[\s\S]*?\]/gi,
      " [이미지] "
    )

    // 대괄호가 없는 data:image 형식 제거
    .replace(
      /data:image\/[a-z0-9.+-]+;base64,[A-Za-z0-9+/=\r\n]+/gi,
      " [이미지] "
    )

    // 문자열로 남은 HTML 줄바꿈 제거
    .replace(/<br\s*\/?>/gi, " ")

    // HTML 공백 문자 제거
    .replace(/&nbsp;|&#160;/gi, " ")

    // 연속된 이미지 표시 정리
    .replace(/(?:\s*\[이미지\]\s*)+/g, " [이미지] ")

    // 연속 공백 정리
    .replace(/\s+/g, " ")
    .trim();
};

/**
 * 문자열의 첫 번째 숫자를 Number로 변환합니다.
 */
const toNumberOrNull = (value) => {
  const matched = cleanText(value).match(/\d+/);

  if (!matched) {
    return null;
  }

  return Number(matched[0]);
};

/**
 * HTML 노드에서 추출한 항목명과 값을 배열로 정리합니다.
 */
const labels = Array.isArray(extracted.fieldLabels)
  ? extracted.fieldLabels.map(cleanText)
  : [];

const values = Array.isArray(extracted.fieldValues)
  ? extracted.fieldValues.map(cleanText)
  : [];

/**
 * 항목명과 값을 객체로 변환합니다.
 *
 * 예:
 * {
 *   대상: "초등학생 1~3학년",
 *   강사: "설숙자",
 *   모집인원: "10"
 * }
 */
const detailFields = {};

for (let index = 0; index < labels.length; index++) {
  const label = labels[index];
  const value = values[index] ?? "";

  if (label) {
    detailFields[label] = value;
  }
}

/**
 * 상세 본문 정리
 */
const bodyText = cleanContentText(extracted.bodyText);
const rawText = cleanContentText(extracted.rawText);

/**
 * 첨부파일 이름과 URL 배열 정리
 */
const attachmentNames = Array.isArray(extracted.attachmentNames)
  ? extracted.attachmentNames.map(cleanText)
  : extracted.attachmentNames
    ? [cleanText(extracted.attachmentNames)]
    : [];

const attachmentUrls = Array.isArray(extracted.attachmentUrls)
  ? extracted.attachmentUrls.map(cleanText)
  : extracted.attachmentUrls
    ? [cleanText(extracted.attachmentUrls)]
    : [];

/**
 * 첨부파일 상대 URL을 절대 URL로 변환합니다.
 */
const normalizeAttachmentUrl = (value) => {
  const href = cleanText(value).replace(/&amp;/g, "&");

  if (!href) {
    return null;
  }

  if (
    href.startsWith("http://") ||
    href.startsWith("https://")
  ) {
    return href;
  }

  const baseUrl =
    cleanText(config.baseUrl) ||
    "https://www.geumjeong.go.kr";

  return `${baseUrl}${href.startsWith("/") ? "" : "/"}${href}`;
};

/**
 * URL 인코딩된 파일명을 안전하게 변환합니다.
 */
const safeDecodeURIComponent = (value) => {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
};

/**
 * 파일명 또는 URL에서 확장자를 추출합니다.
 */
const extractFileType = (fileName, fileUrl) => {
  const target =
    cleanText(fileName) ||
    cleanText(fileUrl).split("?")[0];

  const matched = target.match(/\.([a-z0-9]{1,10})$/i);

  return matched
    ? matched[1].toLowerCase()
    : null;
};

/**
 * 첨부파일 메타데이터 배열 생성
 */
const attachments = [];
const seenAttachmentKeys = new Set();

const attachmentCount = Math.max(
  attachmentNames.length,
  attachmentUrls.length
);

for (let index = 0; index < attachmentCount; index++) {
  const fileUrl = normalizeAttachmentUrl(
    attachmentUrls[index]
  );

  let fileName = cleanText(
    attachmentNames[index]
  );

  // 화면에 파일명이 없으면 URL 마지막 부분을 사용
  if (!fileName && fileUrl) {
    const urlFileName = fileUrl
      .split("?")[0]
      .split("/")
      .pop();

    fileName = safeDecodeURIComponent(
      urlFileName || ""
    );
  }

  if (!fileName && !fileUrl) {
    continue;
  }

  const attachmentKey =
    fileUrl || fileName;

  if (seenAttachmentKeys.has(attachmentKey)) {
    continue;
  }

  seenAttachmentKeys.add(attachmentKey);

  attachments.push({
    fileName: fileName || null,
    fileUrl,
    fileType: extractFileType(
      fileName,
      fileUrl
    ),
    extractionStatus: "PENDING",
  });
}

const hasUnparsedAttachments =
  attachments.length > 0;

/**
 * 교육기간을 시작일과 종료일로 분리합니다.
 */
const educationPeriod = cleanText(
  detailFields["교육기간"]
);

const educationDateMatch = educationPeriod.match(
  /(\d{4}-\d{2}-\d{2})\s*~\s*(\d{4}-\d{2}-\d{2})/
);

const educationStartDate = educationDateMatch
  ? educationDateMatch[1]
  : null;

const educationEndDate = educationDateMatch
  ? educationDateMatch[2]
  : null;

/**
 * 상세 본문에서 장소를 추출합니다.
 *
 * 교육장소, 공연장소, 행사장소 등을 지원합니다.
 */
const locationMatch = bodyText.match(
  /(?:교육장소|공연장소|행사장소|수업장소|강의장소|장소)\s*[:：]\s*(.*?)(?=\s*(?:[-–—]\s*)?(?:교육대상|공연대상|행사대상|대상|교육내용|공연내용|행사내용|내용|재료비|준비물|※|★|$))/
);

const location = locationMatch
  ? cleanText(locationMatch[1])
  : null;

/**
 * 비용 또는 재료비를 추출합니다.
 */
const extractFeeText = (text) => {
  const source = cleanText(text);

  const freeMatch = source.match(
    /(?:재료비|수강료|참가비|비용)\s*[:：]?\s*(무료|없음)/
  );

  if (freeMatch) {
    return cleanText(freeMatch[1]);
  }

  const moneyMatch = source.match(
    /(?:재료비|수강료|참가비|비용)\s*[:：]?\s*((?:(?:\d+\s*회(?:차|당)?\s*[:：]?\s*)?\d{1,3}(?:,\d{3})*\s*원(?:\s*,?\s*\d+\s*회\s*\d{1,3}(?:,\d{3})*\s*원)?))/
  );

  return moneyMatch
    ? cleanText(moneyMatch[1])
    : null;
};

const feeText = extractFeeText(bodyText);

/**
 * 준비물을 추출합니다.
 */
const extractPreparationText = (text) => {
  const source = cleanText(text);

  const match = source.match(
    /(?:학습자\s*)?준비물\s*[:：]?\s*(.*?)(?=\s*(?:교재비|강의실\s*준비|차시|교육내용|수업내용|세부\s*교육내용|<안내\s*사항>|안내\s*사항|문의사항|문의처|문의전화|-\s*대상\s*이외|※|★|$))/
  );

  if (!match) {
    return null;
  }

  const result = cleanText(match[1]);

  if (
    !result ||
    result === "ㅡ" ||
    result === "-"
  ) {
    return null;
  }

  return result;
};

const preparationText =
  extractPreparationText(bodyText);

/**
 * 문의 문구 뒤에 있는 전화번호만 추출합니다.
 *
 * 이미지 파일명의 숫자를 전화번호로 오인하지 않도록
 * "문의사항", "문의처", "문의전화", "문의"가 반드시 필요합니다.
 */
const extractContactText = (text) => {
  const source = cleanText(text);

  const contactMatch = source.match(
    /(?:문의사항|문의처|문의전화|문의)\s*[:：☎]?\s*(0\d{1,2})[\s)-]*(\d{3,4})[\s-]*(\d{4})/
  );

  if (!contactMatch) {
    return null;
  }

  return `${contactMatch[1]}-${contactMatch[2]}-${contactMatch[3]}`;
};

const contactText =
  extractContactText(bodyText);

/**
 * 회차 날짜를 YYYY-MM-DD 형식으로 변환합니다.
 *
 * 예:
 * 07/31 → 2026-07-31
 * 8.4 → 2026-08-04
 */
const normalizeSessionDate = (
  dateValue,
  defaultYear
) => {
  const match = String(dateValue ?? "").match(
    /(\d{1,2})[./](\d{1,2})/
  );

  if (!match) {
    return cleanText(dateValue) || null;
  }

  const month = match[1].padStart(2, "0");
  const day = match[2].padStart(2, "0");

  return `${defaultYear}-${month}-${day}`;
};

/**
 * 상세 본문에서 회차별 일정과 활동을 추출합니다.
 */
const extractSessions = (
  text,
  startDate
) => {
  const source = cleanText(text);

  const sessionHeaderMatch = source.match(
    /차시\s+일자\s+(?:세부\s*)?(?:교육내용|강의내용|활동내용)/
  );

  if (!sessionHeaderMatch) {
    return [];
  }

  let sessionSection = source.slice(
    sessionHeaderMatch.index +
      sessionHeaderMatch[0].length
  );

  // 표의 추가 열 제목 제거
  sessionSection = sessionSection.replace(
    /^(?:교수방법|주제|도서명|교재|활동자료|예시작|담당\s*강사|\([^)]*\)|\s)+/i,
    ""
  );

  // 안내 사항 이후는 회차 내용이 아님
  sessionSection = sessionSection
    .split(/<?\s*안내\s*사항\s*>?/i)[0]
    .trim();

  const defaultYear =
    startDate?.match(/^\d{4}/)?.[0] ||
    String(new Date().getFullYear());

  const sessions = [];

  const sessionPattern =
    /(?:^|\s)(\d{1,2})\s+(\d{1,2}[./]\d{1,2})(?:\s*\([^)]+\))?\s+([\s\S]*?)(?=\s+\d{1,2}\s+\d{1,2}[./]\d{1,2}(?:\s*\([^)]+\))?\s+|$)/g;

  let match;

  while (
    (match = sessionPattern.exec(sessionSection)) !==
    null
  ) {
    const sessionNumber = Number(match[1]);

    const dateText = normalizeSessionDate(
      match[2],
      defaultYear
    );

    let activity = cleanText(match[3]);

    activity = activity
      .replace(
        /\s*(?:담당\s*강사|교수방법|도서명|주제)\s*$/i,
        ""
      )
      .trim();

    if (!activity) {
      continue;
    }

    sessions.push({
      sessionNumber,
      dateText,
      activity,
    });
  }

  return sessions;
};

const sessions = extractSessions(
  bodyText,
  educationStartDate
);

/**
 * 최종 CrawledProgram DTO
 */
const dto = {
  sourcePostId:
    cleanText(program.sourcePostId),

  sourceType:
    config.sourceType ||
    "GEUMJEONG_SMALL_LIBRARY",

  title:
    cleanText(extracted.detailTitle) ||
    cleanText(program.title),

  targetAudience:
    cleanText(detailFields["대상"]) || null,

  instructor:
    cleanText(detailFields["강사"]) || null,

  capacity:
    toNumberOrNull(
      detailFields["모집인원"]
    ),

  currentApplicants:
    program.currentApplicants ?? null,

  applicationStatus:
    cleanText(
      extracted.applicationStatus
    ) || null,

  educationStartDate,
  educationEndDate,

  location,
  feeText,
  preparationText,
  contactText,

  notices:
    bodyText || null,

  sessions,

  attachments,
  hasUnparsedAttachments,

  sourceUrl:
    cleanText(program.sourceUrl),

  rawText:
    rawText || bodyText,

  crawledAt:
    new Date().toISOString(),
};

return {
  json: dto,
};
